diff --git a/src/main/java/org/jsoup/Jsoup.java b/src/main/java/org/jsoup/Jsoup.java
index d25c1869..8e87f530 100644
--- a/src/main/java/org/jsoup/Jsoup.java
+++ b/src/main/java/org/jsoup/Jsoup.java
@@ -247,7 +247,70 @@ public class Jsoup {
      @see #clean(String, org.jsoup.safety.Whitelist) 
      */
     public static boolean isValid(String bodyHtml, Whitelist whitelist) {
-        return new Cleaner(whitelist).isValid(parseBodyFragment(bodyHtml, ""));
+        // Check if the input looks like a full document rather than a body fragment
+        // Body fragments shouldn't contain html, head, or body tags
+        String lowerInput = bodyHtml.toLowerCase();
+        if (lowerInput.contains("<html") || lowerInput.contains("<head") || lowerInput.contains("</head>")) {
+            return false;
+        }
+
+        Document parsed = parseBodyFragment(bodyHtml, "");
+
+        // Check if the parsed HTML structure differs from the original input
+        // This detects malformed HTML that gets auto-corrected by the parser (e.g., missing close tags)
+        if (!parsedStructureMatchesInput(bodyHtml, parsed)) {
+            return false;
+        }
+
+        return new Cleaner(whitelist).isValid(parsed);
+    }
+
+    private static boolean parsedStructureMatchesInput(String original, Document parsed) {
+        // Get the parsed HTML from the body
+        String parsedBody = parsed.body().html();
+
+        // Extract tag signatures from both (opening and closing tag names only)
+        String originalTags = extractTagSignature(original);
+        String parsedTags = extractTagSignature(parsedBody);
+
+        // Compare tag structures
+        return originalTags.equalsIgnoreCase(parsedTags);
+    }
+
+    private static String extractTagSignature(String html) {
+        // Extract just the tag structure: open/close tag names, ignoring attributes and text
+        StringBuilder sig = new StringBuilder();
+        int i = 0;
+        while (i < html.length()) {
+            int tagStart = html.indexOf('<', i);
+            if (tagStart == -1) break;
+
+            int tagEnd = html.indexOf('>', tagStart);
+            if (tagEnd == -1) break;
+
+            String tag = html.substring(tagStart + 1, tagEnd);
+
+            // Skip comments, doctype, etc.
+            if (tag.startsWith("!") || tag.startsWith("?")) {
+                i = tagEnd + 1;
+                continue;
+            }
+
+            // Extract tag name (first word after potential /)
+            String[] parts = tag.split("\\s");
+            String tagName = parts[0].replaceFirst("^/", "").toLowerCase();
+
+            if (tag.startsWith("/")) {
+                sig.append("</").append(tagName).append(">");
+            } else if (tag.endsWith("/")) {
+                sig.append("<").append(tagName).append("/>");
+            } else {
+                sig.append("<").append(tagName).append(">");
+            }
+
+            i = tagEnd + 1;
+        }
+        return sig.toString();
     }

 }
diff --git a/src/main/java/org/jsoup/safety/Cleaner.java b/src/main/java/org/jsoup/safety/Cleaner.java
index 7e0eb28d..2c0a31d6 100644
